<?php require __DIR__.'/bootstrap.php';$where=[];$args=[];if($q=clean($_GET['q']??'')){$where[]='title LIKE ?';$args[]="%$q%";}if($r=clean($_GET['relevance']??'')){$where[]='relevance_status=?';$args[]=$r;}else{$where[]="relevance_status<>'unrelated'";}$st=db()->prepare('SELECT * FROM news WHERE '.implode(' AND ',$where).' ORDER BY published_at DESC,discovered_at DESC LIMIT 200');$st->execute($args);respond(['items'=>$st->fetchAll()]);
